local root=app.params["root"]
local s=app.open(root.."/A.aseprite");assert(s.width==512 and s.height==512 and #s.layers==10 and #s.frames==1,"Architecture source contract")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[1].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-shadow.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[2].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-foundation.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[3].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-walls.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[4].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-framing.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[5].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-doors.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[6].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-windows.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[7].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-roof.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[8].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-chimney.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[9].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-porch.png")
for _,l in ipairs(s.layers) do l.isVisible=false end;s.layers[10].isVisible=true;local im=Image(s.spec);im:drawSprite(s,1);im:saveAs(root.."/A-trim.png")
s:close()
